"""Build the standalone PostgreSQL deployment from immutable SQL migrations."""

from hashlib import sha256
from pathlib import Path
import argparse
import sys

ROOT = Path(__file__).resolve().parent


def build() -> str:
    result = [
        "-- Generated by build_deploy.py. Edit migration sources, then rebuild.\n",
        "-- PostgreSQL 17+; run against the selected application database.\n",
        "-- Sources: repository SRS 1.1-draft, Metro-SRS-v1.1 (11 November 2026),\n",
        "-- and docs/database/drawsql-srs-v1.1-review.md.\n",
        "BEGIN;\nSET LOCAL lock_timeout = '15s';\n",
        "SET LOCAL statement_timeout = '5min';\nSET LOCAL client_encoding = 'UTF8';\n",
        "SELECT pg_advisory_xact_lock(73190624011213);\n",
        "DO $preflight$ BEGIN\n",
        "  IF current_setting('server_version_num')::integer < 170000 THEN\n",
        "    RAISE EXCEPTION 'Metro requires PostgreSQL 17 or newer';\n  END IF;\n",
        "  IF current_setting('server_encoding') <> 'UTF8' THEN\n",
        "    RAISE EXCEPTION 'Metro requires a UTF8 database';\n  END IF;\n",
        "  IF to_regnamespace('metro') IS NOT NULL\n",
        "     AND to_regclass('metro.schema_migrations') IS NULL\n",
        "     AND EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace\n",
        "                 WHERE n.nspname = 'metro' AND c.relkind IN ('r','p')) THEN\n",
        "    RAISE EXCEPTION 'Existing unversioned metro schema; review it before deployment';\n",
        "  END IF;\nEND $preflight$;\n",
        "CREATE EXTENSION IF NOT EXISTS btree_gist WITH SCHEMA public;\n",
        "CREATE SCHEMA IF NOT EXISTS metro;\n",
        "CREATE TABLE IF NOT EXISTS metro.schema_migrations (\n",
        "  version integer PRIMARY KEY, name text NOT NULL, checksum char(64) NOT NULL,\n",
        "  applied_at timestamptz NOT NULL DEFAULT clock_timestamp(),\n",
        "  applied_by text NOT NULL DEFAULT current_user\n);\n",
        "SET LOCAL search_path = metro, public, pg_catalog;\n",
    ]
    files = sorted((ROOT / "migrations").glob("[0-9][0-9][0-9]_*.sql"))
    if not files:
        raise ValueError("No migrations found")
    for expected, file in enumerate(files, start=1):
        version = int(file.name.split("_", 1)[0])
        if version != expected:
            raise ValueError(f"Expected migration {expected:03}, found {file.name}")
        source = file.read_text(encoding="utf-8").replace("\r\n", "\n")
        checksum = sha256(source.encode("utf-8")).hexdigest()
        tag = f"$migration_{version:03}$"
        if tag in source:
            raise ValueError(f"Reserved dollar quote in {file.name}")
        result.extend([
            f"\n-- {file.name}\nDO {tag}\nBEGIN\n",
            f"  IF EXISTS (SELECT 1 FROM metro.schema_migrations WHERE version = {version}) THEN\n",
            f"    IF NOT EXISTS (SELECT 1 FROM metro.schema_migrations WHERE version = {version}\n",
            f"                   AND name = '{file.name}' AND checksum = '{checksum}') THEN\n",
            f"      RAISE EXCEPTION 'Migration {version:03} checksum mismatch; add a new migration';\n",
            "    END IF;\n",
            f"    RAISE NOTICE 'Migration {version:03} already applied';\n    RETURN;\n  END IF;\n\n",
            source,
            "\n",
            f"  INSERT INTO metro.schema_migrations (version, name, checksum)\n",
            f"  VALUES ({version}, '{file.name}', '{checksum}');\n",
            f"END {tag};\n",
        ])
    result.append("\nCOMMIT;\n")
    return "".join(result)


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="Fail if deploy.sql needs rebuilding")
    args = parser.parse_args()
    content = build()
    target = ROOT / "deploy.sql"
    if args.check:
        if not target.exists() or target.read_text(encoding="utf-8") != content:
            print("deploy.sql is out of date; run build_deploy.py", file=sys.stderr)
            return 1
        print("deploy.sql matches all migration sources")
    else:
        target.write_text(content, encoding="utf-8", newline="\n")
        print(f"Built {target}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
